/**
 * Drift guard for the Flutter component library's art (client/lib/ui/olive_art_data.dart).
 *
 * The data is generated by tools/gen-olive-icons.mjs from tools/design-reference/kit.js
 * (a verbatim snapshot of the premium kit's icon table and illustration code, because the reference
 * kit itself lives outside git). This suite fails if the committed Dart is stale against a fresh
 * generation, so the Flutter icons/scenes/spots cannot drift from the kit without CI noticing, and it
 * checks the generator's own invariants (every kit icon present, tokens known, P2 art rules).
 * Same shape as the colour-day vector guard: tools/gen-colour-vectors.mjs + its test.
 *
 * usage: node tools/test/olive_art.test.mjs
 */
import { readFileSync } from 'node:fs';
import { generate, extractBody, parseSvg, TOKENS, SNAPSHOT_PATH, OUT_PATH } from '../gen-olive-icons.mjs';

let pass = 0, fail = 0; const rows = [];
const check = (g, n, a, e) => { const ok = String(a) === String(e); ok ? pass++ : fail++; rows.push({ g, n, ok, a: String(a), e: String(e) }); };
const rd = (p) => readFileSync(p, 'utf8').replace(/\r\n/g, '\n');

const snapshot = rd(SNAPSHOT_PATH);
const committed = rd(OUT_PATH);
const fresh = generate();

// ---------------------------------------------------------------- drift guard
check('drift', 'committed olive_art_data.dart equals a fresh generation from the snapshot', committed === fresh, true);
check('drift', 'the generated file says it is generated and not to be edited', /GENERATED by tools\/gen-olive-icons\.mjs/.test(committed) && /DO NOT EDIT/.test(committed), true);
check('drift', 'the generated file carries the CI-verified header', committed.startsWith('// No longer UNVERIFIED — verified by CI'), true);

// ------------------------------------------------------------------- snapshot
check('snapshot', 'the input is the shared committed kit snapshot', SNAPSHOT_PATH.replace(/\\/g, '/').endsWith('tools/design-reference/kit.js'), true);
check('snapshot', 'it still has the icon table', snapshot.includes('var IC={'), true);
check('snapshot', 'it still has OB.scene and OB.spot', snapshot.includes('OB.scene=function') && snapshot.includes('OB.spot=function'), true);
check('snapshot', 'extractBody finds the block', extractBody(snapshot).includes('var IC={'), true);
let threw = false; try { extractBody('not a kit'); } catch { threw = true; }
check('snapshot', 'extractBody refuses a file that is not the kit', threw, true);

// ------------------------------------------------------------ icon completeness
const iconBlock = snapshot.slice(snapshot.indexOf('var IC={'), snapshot.indexOf('OB.ICONS='));
const kitIcons = [...iconBlock.matchAll(/(?:^|[\s,{])([A-Za-z][A-Za-z0-9]*):'</gm)].map((m) => m[1]);
check('icons', 'kit icon table has more than 90 icons', kitIcons.length > 90, true);
const dartIcons = [...committed.matchAll(/^  static const String (\w+) = '\1';$/gm)].map((m) => m[1]);
check('icons', 'OliveIcons has exactly the kit icon names, in order', dartIcons.join(','), kitIcons.join(','));
const dataKeys = [...committed.slice(committed.indexOf('kOliveIconData'), committed.indexOf('kOliveSceneData')).matchAll(/^  '(\w+)': \[$/gm)].map((m) => m[1]);
check('icons', 'every icon has geometry', dataKeys.join(','), kitIcons.join(','));
for (const n of ['home', 'chevR', 'micoff', 'wifioff', 'fingerprint', 'check2', 'skip', 'star']) {
  check('icons', `icon ${n} is present`, dartIcons.includes(n), true);
}

// ------------------------------------------------------ scenes / spots present
const need = { scenes: 'day night garden kitchen car classroom bedroom park sea twohouses'.split(' '), spots: 'family houses envelope key shield lock phone tablet video mic leaf'.split(' ') };
const sceneNames = /kOliveSceneNames = \[(.*?)\];/.exec(committed)[1].match(/'(\w+)'/g).map((s) => s.slice(1, -1));
const spotNames = /kOliveSpotNames = \[(.*?)\];/.exec(committed)[1].match(/'(\w+)'/g).map((s) => s.slice(1, -1));
for (const n of need.scenes) check('scenes', `scene ${n} is present`, sceneNames.includes(n), true);
for (const n of need.spots) check('spots', `spot ${n} is present`, spotNames.includes(n), true);
const banned = /star|trophy|medal|crown|score|streak|rank/i;
check('P2', 'no scene or spot is named like a star, trophy, score or streak', [...sceneNames, ...spotNames].filter((n) => banned.test(n)).join(',') || 'none', 'none');
check('P2', 'the leaf is the celebration image', spotNames.includes('leaf'), true);

// ------------------------------------------------------------------ tokens
const used = new Set([...committed.matchAll(/OTok\.(\w+)/g)].map((m) => m[1]));
check('tokens', 'every palette token the art uses is a known token', [...used].filter((t) => !TOKENS.includes(t)).join(',') || 'none', 'none');
check('tokens', 'the art uses the primary palette tokens', ['pri', 'priD', 'priC', 'accent', 'surface'].every((t) => used.has(t)), true);
check('tokens', 'no raw CSS leaks into the Dart (var(--, color-mix)', /var\(--|color-mix/.test(committed), false);

// ------------------------------------------------------------ generator parser
const sq = parseSvg('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="5" width="18" height="16" rx="3"/></svg>', { iconMode: true });
check('parser', 'a rounded rect becomes one closed path', sq.nodes.length === 1 && sq.nodes[0].ops.at(-1) === 4, true);
const arc = parseSvg('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M5 11a7 7 0 0014 0"/></svg>');
check('parser', 'compact arc flags (0014) parse as flags 0,0 then x 14', Math.abs(arc.nodes[0].ops.at(-2) - 19) < 1e-6 && Math.abs(arc.nodes[0].ops.at(-1) - 11) < 1e-6, true);
check('parser', 'a half circle arc becomes cubic segments', arc.nodes[0].ops.filter((v, i, a) => v === 3).length >= 2, true);
let t2 = false; try { parseSvg('<svg viewBox="0 0 1 1"><blink/></svg>'); } catch { t2 = true; }
check('parser', 'an unsupported element is refused, not ignored', t2, true);
const grp = parseSvg('<svg viewBox="0 0 10 10"><g opacity=".5" fill="#fff"><circle cx="1" cy="1" r="1"/></g></svg>');
check('parser', 'group opacity is preserved as a group', grp.nodes[0].group === true && grp.nodes[0].opacity === 0.5, true);
check('parser', 'fixed hex colours are parsed', grp.nodes[0].children[0].fill.v === 0xffffff, true);

// ------------------------------------------------------------------- report
for (const r of rows.filter((r) => !r.ok)) console.log(`  FAIL ${r.g}: ${r.n} (got ${r.a}, want ${r.e})`);
console.log(`${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
